// Observables from the normalized alert: Suricata (src_ip/dest_ip) or host (srcip/dstip). Nulls skipped.
const n = $('Normalize').first().json;
const caseId = $('HTTP Request').first().json._id;

return [[n.source_ip, 'Source address'], [n.dest_ip, 'Target address']]
  .filter(([data]) => data)
  .map(([data, message]) => ({ json: { caseId, dataType: 'ip', data, message } }));

const alert = $('Webhook').first().json.body;
const caseId = $('Code in JavaScript').first().json.caseId;

// Each item is a Cortex waitreport response (Cortex waits up to 1 minute for the job).
// Success  -> taxonomies.  Failure -> the analyzer finished with an error (reported as such).
// Anything else (Waiting/InProgress after the limit, or a request error) -> unavailable. Never "clean".
const findings = [];

for (const item of $input.all()) {
  const j = item.json;
  const addr = j.data || 'unknown';
  const worker = j.workerName || 'analyzer';

  if (j.status === 'Success' && j.report?.summary?.taxonomies) {
    const tax = j.report.summary.taxonomies
      .map(t => `${t.predicate} ${t.value} (${t.level})`)
      .join(', ');
    findings.push(`${worker} on ${addr}: ${tax || 'finished, no taxonomies returned'}`);
  } else if (j.status === 'Failure') {
    findings.push(`${worker} on ${addr}: analyzer finished with an error: ${j.errorMessage || j.report?.errorMessage || 'no message'}`);
  } else {
    findings.push(`${worker} on ${addr}: unavailable (job did not finish within 60s${j.status ? ', last status ' + j.status : ''})`);
  }
}

return [{
  json: {
    caseId,
    alert,
    enrichment: findings.join('\n'),
  }
}];

const agentOut = $('AI Agent').first().json.output;
const caseId = $('HTTP Request').first().json._id;

let verdict;
try {
  verdict = JSON.parse(agentOut);
} catch (e) {
  verdict = {
    verdict: "needs_investigation",
    confidence: "low",
    severity: "medium",
    summary: "Agent output could not be parsed. Manual triage required.",
    reasoning: String(agentOut).slice(0, 500),
    escalate: true,
    recommended_next_steps: ["Review raw alert manually"]
  };
}

const sevMap = { critical: 4, high: 3, medium: 2, low: 1, informational: 1 };

const noteBody = [
  `## L1 Agent Triage`,
  ``,
  `**Verdict:** ${verdict.verdict}  (confidence: ${verdict.confidence})`,
  `**Severity:** ${verdict.severity}`,
  `**Class:** ${verdict.alert_class}`,
  `**Escalate:** ${verdict.escalate}`,
  ``,
  `### Summary`,
  verdict.summary,
  ``,
  `### Reasoning`,
  verdict.reasoning,
  ``,
  `### Recommended next steps`,
  ...(verdict.recommended_next_steps || []).map(s => `- ${s}`),
  ``,
  `_Generated by L1 agent. Awaiting analyst approval._`
].join('\n');

return [{
  json: {
    caseId,
    verdict: verdict.verdict,
    severity: verdict.severity,
    sevNumber: sevMap[verdict.severity] || 2,
    escalate: verdict.escalate,
    noteBody
  }
}];

// n8n Code node "Normalize" (mode: Run Once for All Items).
// Sits between Webhook and the existing Filter/enrichment chain.
// Suricata alerts carry data.src_ip / data.dest_ip; host alerts (sshd, syscheck,
// Kali, Mac) carry data.srcip / data.dstip. This flattens both into one shape.
// `raw` keeps the original alert, so old references to $json.body.X become $json.raw.X.
const out=[];
for (const item of $input.all()){
  const a=item.json.body||item.json, d=a.data||{}, ag=a.agent||{}, r=a.rule||{}, sc=a.syscheck||{};
  out.push({json:{
    agent_name:ag.name||'unknown', source_ip:d.src_ip||d.srcip||null,
    dest_ip:d.dest_ip||d.dstip||null, user:d.dstuser||d.srcuser||null,
    file:sc.path||null, rule_id:r.id||null, rule_level:r.level||0,
    rule_desc:r.description||'', rule_groups:r.groups||[],
    signature:(d.alert&&d.alert.signature)||r.description||'Wazuh alert',
    timestamp:a.timestamp||null, raw:a }});
}
return out;

// Host alerts with no IP (file integrity, local auth...) skip Cortex but still get L1 triage.
// Same output shape as 'Build Enrichment Summary'.
return [{ json: {
  caseId: $('HTTP Request').first().json._id,
  alert: $('Normalize').first().json.raw,
  enrichment: 'No IP observables on this alert; no reputation lookup performed.',
} }];

// Format Email: turn the L1 markdown note into HTML + a plain-text fallback. Notification only.
const pv = $('Parse Verdict').first().json;
const nz = $('Normalize').first().json;
const caseUrl = `http://<SERVICES_IP>:9000/cases/${$('HTTP Request').first().json._id}/details`;
const FIRST = 'L1 agent escalation (notification only; nothing has been actioned).';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const inline = s => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/(^|\s)_([^_]+?)_(?=\s|$|[.,;:])/g, '$1<em>$2</em>');

function mdToHtml(md) {
  const out = []; let list = false;
  for (const line of String(md || '').split('\n')) {
    const li = line.match(/^\s*-\s+(.*)$/);
    if (li) { if (!list) { out.push('<ul>'); list = true; } out.push(`<li>${inline(li[1])}</li>`); continue; }
    if (list) { out.push('</ul>'); list = false; }
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) { const n = Math.min(h[1].length + 1, 6); out.push(`<h${n}>${inline(h[2])}</h${n}>`); }
    else if (line.trim()) out.push(`<p>${inline(line)}</p>`);
  }
  if (list) out.push('</ul>');
  return out.join('\n');
}
const mdToText = md => String(md || '').replace(/^#{1,6}\s+/gm, '').replace(/\*\*(.+?)\*\*/g, '$1').replace(/(^|\s)_([^_]+?)_(?=\s|$|[.,;:])/g, '$1$2');

const facts = [
  ['Agent', nz.agent_name],
  ['Rule', `${nz.rule_id} (level ${nz.rule_level}) - ${nz.rule_desc}`],
  ['Source', nz.source_ip || 'n/a'],
  ['Destination', nz.dest_ip || 'n/a'],
];

const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.45;color:#1a1a1a;max-width:720px">
<p><strong>${esc(FIRST)}</strong></p>
<table style="border-collapse:collapse;margin:8px 0">
${facts.map(([k, v]) => `<tr><td style="padding:2px 12px 2px 0;color:#555">${esc(k)}</td><td style="padding:2px 0">${esc(v)}</td></tr>`).join('\n')}
</table>
<hr style="border:none;border-top:1px solid #ddd">
${mdToHtml(pv.noteBody)}
<hr style="border:none;border-top:1px solid #ddd">
<p>Case: <a href="${esc(caseUrl)}">${esc(caseUrl)}</a></p>
<p style="color:#555">Status New, unassigned. A human decides every next step.</p>
</div>`;

const text = [
  FIRST, '',
  ...facts.map(([k, v]) => `${k}: ${v}`), '',
  mdToText(pv.noteBody), '',
  `Case: ${caseUrl}`,
  'Status New, unassigned. A human decides every next step.',
].join('\n');

return [{ json: { html, text } }];

// One Cortex job per (observable, analyzer). Downstream waitreport + Build Enrichment Summary
// already handle many results, so the L1 agent still runs once per alert.
const analyzers = ["89b6a8415bce4a0557a2bf15bb5436cd::AbuseIPDB_2_0", "0e2a20abae837977fed18ad2359401cd::VirusTotal_GetReport_3_1"];
return $input.all().flatMap(i => analyzers.map(a => ({ json: { ...i.json, analyzer: a } })));
